        return asArray(data.results).slice(0, max2).map((r) => {
          const row = asRecord(r);
          return {
            title: asText(row.title),
            url: asText(row.url),
            content: asText(row.content) || asText(row.snippet)
          };
        }).filter((r) => r.url);
