// src/editor/autoprompt.ts
var acceptAnnotation = import_state2.Annotation.define();
async function requestSuggestion(plugin, view) {
  const provider = plugin.getProvider();
  const state = view.state;
  const pos = state.selection.main.head;
  const before = state.doc.sliceString(Math.max(0, pos - 2e3), pos);
  const after = state.doc.sliceString(
    pos,
    Math.min(state.doc.length, pos + 500)
  );
  try {
    const raw = (await provider.complete(buildAutopromptPrompt(before, after), {
      temperature: plugin.settings.temperature,
      maxTokens: 256
    })).content;
    const text = raw.trim();
    if (text && view.state.selection.main.head === pos) {
      view.dispatch({ effects: setSuggestion.of({ text, pos }) });
    }
  } catch (e) {
  }
}
function acceptSuggestion(view) {
  const val = view.state.field(suggestionField);
  if (!val)
    return false;
  view.dispatch({
    changes: { from: val.pos, insert: val.text },
    effects: setSuggestion.of(null),
    annotations: acceptAnnotation.of(true)
  });
  return true;
}
function clearSuggestion(view) {
  if (!view.state.field(suggestionField))
    return false;
  view.dispatch({ effects: setSuggestion.of(null) });
  return true;
}
function createRealtimeExtension(plugin) {
  const realtimePlugin = import_view2.ViewPlugin.fromClass(
    class {
      constructor() {
        this.timer = null;
      }
      update(u) {
        if (!plugin.settings.realtimeEnabled)
          return;
        if (!u.docChanged)
          return;
        if (u.transactions.some((t2) => t2.annotation(acceptAnnotation)))
          return;
        if (this.timer !== null)
          window.clearTimeout(this.timer);
        const view = u.view;
        const debounce = plugin.settings.realtimeDebounceMs;
        this.timer = window.setTimeout(() => {
          void requestSuggestion(plugin, view);
        }, debounce);
      }
      destroy() {
        if (this.timer !== null)
          window.clearTimeout(this.timer);
      }
    }
  );
  return [
    suggestionField,
    ghostDecorations,
    realtimePlugin,
    import_state2.Prec.highest(
      import_view2.keymap.of([
        { key: "Tab", run: (view) => acceptSuggestion(view) },
        { key: "Escape", run: (view) => clearSuggestion(view) }
      ])
    )
  ];
}
async function autopromptAtCursor(plugin, editor) {
  const provider = plugin.getProvider();
  const pos = editor.getCursor();
  const before = editor.getRange({ line: 0, ch: 0 }, pos);
  const end = editor.offsetToPos(editor.getValue().length);
  const after = editor.getRange(pos, end);
  const raw = (await provider.complete(buildAutopromptPrompt(before, after), {
    temperature: plugin.settings.temperature,
    maxTokens: 512
  })).content;
  const text = raw.trim();
  if (text) {
    editor.replaceSelection(text);
  } else {
    new import_obsidian13.Notice(t("notice.noSuggestion"));
  }
}

