// src/migrate.ts
function migrateSettings(loaded, settings, app) {
  if (!settings.modelLinks || settings.modelLinks.length === 0) {
    const hasLegacy = loaded.provider || loaded.openaiApiKey || loaded.openaiBaseUrl || loaded.ollamaBaseUrl || loaded.openaiModel || loaded.ollamaModel;
    if (hasLegacy) {
      const isOllama = loaded.provider === "ollama";
      const modelId = asText(
        isOllama ? loaded.ollamaModel : loaded.openaiModel
      );
      const link = {
        id: genId(),
        name: t("settings.modelLinks.legacyName"),
        type: isOllama ? "ollama" : "openai",
        baseUrl: isOllama ? asText(loaded.ollamaBaseUrl) || DEFAULT_SETTINGS.ollamaBaseUrl : asText(loaded.openaiBaseUrl) || DEFAULT_SETTINGS.openaiBaseUrl,
        apiKey: asText(loaded.openaiApiKey),
        models: modelId ? [modelId] : []
      };
      migrateModelLinkApiKeyToKeychain(app, link);
      delete link.apiKey;
      settings.modelLinks = [link];
      settings.defaultModelLinkId = link.id;
    } else {
      settings.modelLinks = [];
      settings.defaultModelLinkId = "";
    }
  }
  if (settings.modelLinks.length > 0 && !settings.modelLinks.some((l) => l.id === settings.defaultModelLinkId)) {
    settings.defaultModelLinkId = settings.modelLinks[0].id;
  }
  for (const link of settings.modelLinks) {
    migrateModelLinkApiKeyToKeychain(
      app,
      link
    );
  }
  const webProviders = [
    "tavily",
    "serper",
    "brave"
  ];
  for (const prov of webProviders) {
    const refField = `${prov}ApiKeyRef`;
    const settingsAny = settings;
    if (settingsAny[refField])
      continue;
    const legacyRefs = loaded[`${prov}ApiKeyRefs`];
    if (Array.isArray(legacyRefs) && legacyRefs.length > 0 && typeof legacyRefs[0] === "string" && legacyRefs[0]) {
      settingsAny[refField] = legacyRefs[0];
      continue;
    }
    const legacyKeys = loaded[`${prov}ApiKeys`];
    if (Array.isArray(legacyKeys) && legacyKeys.length > 0) {
      const ref = migrateWebApiKeysToKeychain(
        app,
        prov,
        legacyKeys
      );
      if (ref)
        settingsAny[refField] = ref;
    }
  }
  delete settings.tavilyApiKeyRefs;
  delete settings.serperApiKeyRefs;
  delete settings.braveApiKeyRefs;
  delete settings.tavilyApiKeys;
  delete settings.serperApiKeys;
  delete settings.braveApiKeys;
  if (!settings.roles || settings.roles.length === 0) {
    const legacy = asText(loaded.customInstructions);
    if (legacy.trim()) {
      const role = {
        id: genId(),
        name: t("settings.roles.legacyName"),
        prompt: legacy.trim()
      };
      settings.roles = [role];
      settings.defaultRoleId = role.id;
    } else {
      settings.roles = [];
      settings.defaultRoleId = "";
    }
  }
  if (settings.roles.length > 0 && !settings.roles.some((r) => r.id === settings.defaultRoleId)) {
    settings.defaultRoleId = settings.roles[0].id;
  }
  settings.openaiApiKey = "";
}

